with.code:
// The approval decision is policy arithmetic, never the caller's preference.
const e = $('Envelope In').first().json;
const CH = JSON.parse($env.MOS_CHANNELS || '{}');
const p = e.payload;
const channel = CH[p.channel] || {};
const mode = e.policy?.approval_mode || 'channel_conditional';
const autonomy = e.policy?.autonomy_level || 'publish_with_approval';
const brandStatus = $json.status;
const complianceWarn = ($('Compliance Screen').first().json.findings || []).some(f => f.severity === 'warn');

let required = false, reason = null;

if (autonomy === 'suggest' || autonomy === 'draft') { required = true; reason = 'autonomy_level'; }
else if ((channel.requires_gates || []).includes('human_approval')) { required = true; reason = 'channel_requires_approval'; }
else if (mode === 'always') { required = true; reason = 'approval_mode_always'; }
else if (mode === 'channel_conditional' && ['paid', 'owned'].includes(channel.kind)) { required = true; reason = 'high_blast_radius_channel'; }
else if (brandStatus === 'warn' || complianceWarn) { required = true; reason = 'gate_warning'; }
else if (mode === 'sampled' && Math.random() < (e.policy?.sample_rate ?? 0.1)) { required = true; reason = 'sampled'; }

return [{ json: { approval_required: required, reason, brand_status: brandStatus, gates: { rights: 'pass', compliance: $('Compliance Screen').first().json.status, brand: brandStatus } } }];

return [{ json: {
  governance_status: 'blocked',
  may_publish: false,
  findings: $json.findings || $json.failures || [],
  // Blocked runs are parked WITH their findings, not discarded. A human fixes the finding
  // and replays the same trace_id rather than starting over from the original message.
  action: 'park_for_human',
  error: { code: $json.failures ? 'POLICY_BLOCKED' : 'COMPLIANCE_BLOCKED', message: 'Governance gate blocked distribution', retryable: false, at: new Date().toISOString() }
} }];
